/**
 * Response types for the overview page's three read endpoints (docs/09 §9.2):
 * `GET /overview?repo=`, `GET /metrics/trends?range=14d&repo=` and
 * `GET /events?page_size=8`.
 *
 * The shapes come from the Rust DTOs via ts-rs (`web/src/lib/api-types/`,
 * regenerated by CI). Only the fields the UI deliberately narrows — the
 * `state`/`severity` unions and the counts map — are re-declared here; every
 * other field follows the server.
 *
 * The shell's HealthStrip shares `OverviewResponse` and the query key.
 */

import type { IssueState, Severity } from "../../components/ui";
import type { ActiveRun } from "../../lib/api-types/ActiveRun";
import type { AttentionItem } from "../../lib/api-types/AttentionItem";
import type { CiCounts } from "../../lib/api-types/CiCounts";
import type { Health } from "../../lib/api-types/Health";
import type { OverviewResponse as ApiOverviewResponse } from "../../lib/api-types/OverviewResponse";
import type { Queue } from "../../lib/api-types/Queue";
import type { QueueItem } from "../../lib/api-types/QueueItem";
import type { TrendBucket as ApiTrendBucket } from "../../lib/api-types/TrendBucket";
import type { TrendTotals as ApiTrendTotals } from "../../lib/api-types/TrendTotals";
import type { TrendsResponse as ApiTrendsResponse } from "../../lib/api-types/TrendsResponse";

export type OverviewAttentionItem = Omit<AttentionItem, "state" | "severity"> & {
  state: IssueState;
  severity: Severity;
};

export type OverviewActiveRun = ActiveRun;

export type OverviewQueueItem = Omit<QueueItem, "severity"> & {
  severity: Severity;
};

export type OverviewQueue = Omit<Queue, "next"> & {
  next: OverviewQueueItem[];
};

export type OverviewHealth = Health;

export type OverviewCiCounts = CiCounts;

export type OverviewResponse = Omit<
  ApiOverviewResponse,
  "counts" | "attention" | "active_runs" | "queue" | "health" | "ci_24h"
> & {
  /** The API always reports every state (zero-filled). */
  counts: Record<IssueState, number>;
  attention: OverviewAttentionItem[];
  active_runs: OverviewActiveRun[];
  queue: OverviewQueue;
  health: OverviewHealth;
  ci_24h: OverviewCiCounts;
};

/** Shared TanStack Query key: `repo` undefined means the whole instance. */
export function overviewQueryKey(repo?: string | null) {
  return ["overview", repo ?? null] as const;
}

export type TrendsRange = "7d" | "14d" | "30d" | "90d";

export const DEFAULT_TRENDS_RANGE: TrendsRange = "14d";

/** One UTC day bucket; missing days arrive zero-filled from the API. */
export type TrendBucket = ApiTrendBucket;

export type TrendTotals = ApiTrendTotals;

export type TrendsResponse = ApiTrendsResponse;

export function trendsQueryKey(range: TrendsRange = DEFAULT_TRENDS_RANGE, repo?: string | null) {
  return ["trends", range, repo ?? null] as const;
}

export function recentEventsQueryKey(pageSize: number) {
  return ["events", "recent", pageSize] as const;
}
